import type SpatialReference from "../../../../geometry/SpatialReference.js";
import type { JSONSupport } from "../../../../core/JSONSupport.js";
import type { SpatialReferenceProperties } from "../../../../geometry/SpatialReference.js";

/** @since 5.0 */
export interface VerifyCircuitsParametersProperties extends Partial<Pick<VerifyCircuitsParameters, "circuitNames" | "forceVerify" | "synthesizeGeometries">> {
  /**
   * The spatial reference of the returned geometry.
   * If not specified, the geometry is returned in the spatial reference of the feature service.
   *
   * @since 5.1
   * @autocast
   */
  outSpatialReference?: SpatialReferenceProperties | null;
}

/** @since 5.0 */
export default class VerifyCircuitsParameters extends JSONSupport {
  constructor(properties?: VerifyCircuitsParametersProperties);
  /**
   * The names of the circuit or circuits to be verified.
   *
   * @since 5.0
   */
  accessor circuitNames: string[];
  /**
   * Enables circuits to be verified regardless of their status.
   * When `false`, the verify operation returns an error ​if the circuit status is clean​.
   * When `true`, the verify operation will run against clean, dirty, and invalid circuits​.
   * The default is `false`.
   *
   * @default false
   * @since 5.0
   */
  accessor forceVerify: boolean;
  /**
   * The spatial reference of the returned geometry.
   * If not specified, the geometry is returned in the spatial reference of the feature service.
   *
   * @since 5.1
   * @autocast
   */
  get outSpatialReference(): SpatialReference | null | undefined;
  set outSpatialReference(value: SpatialReferenceProperties | null | undefined);
  /**
   * Specifies whether geometries will be inferred and created (synthesized) for the circuits.
   * The default is `false`.
   *
   * @default false
   * @since 5.0
   */
  accessor synthesizeGeometries: boolean;
}